<?php // One-button action form for a table row or a drawer footer: expects $returnPath, $rowAction, $rowConfirm, $rowLabel, $rowIcon, optional $rowClass and $rowFields (hidden fields). ?>
<form method="post" action="<?=e(base_url($rowAction))?>" class="row-action-form" data-flow-form data-confirm="<?=e($rowConfirm)?>"><?=csrf_field()?><input type="hidden" name="_flow_return" value="<?=e($returnPath)?>"><input type="hidden" name="operation_key" value="<?=e(bin2hex(random_bytes(16)))?>"><?php foreach($rowFields??[] as $fieldName=>$fieldValue): ?><input type="hidden" name="<?=e($fieldName)?>" value="<?=e($fieldValue)?>"><?php endforeach; ?><p class="app-alert app-alert-error" data-feed-error role="alert" hidden></p><button type="submit" class="<?=e($rowClass??'btn-primary')?> row-action-button"><i class="bi <?=e($rowIcon)?>" aria-hidden="true"></i><span><?=e($rowLabel)?></span></button></form>
<?php unset($rowFields,$rowClass); ?>
